package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(reader, &n, &k)

	if n == 1 {
		fmt.Println(0)
		return
	}

	// Precompute factorials and inverse factorials up to n
	fact := make([]int, n+1)
	invFact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	invFact[n] = modInv(fact[n], MOD)
	for i := n - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2 up to n
	pow2 := make([]int, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}

	// Precompute powers of 2 inverses up to n
	inv2 := modInv(2, MOD)
	invPow2 := make([]int, n+1)
	invPow2[0] = 1
	for i := 1; i <= n; i++ {
		invPow2[i] = invPow2[i-1] * inv2 % MOD
	}

	// Precompute prefix sums of invPow2
	prefix := make([]int, n+1)
	prefix[0] = invPow2[0]
	for i := 1; i <= n; i++ {
		prefix[i] = (prefix[i-1] + invPow2[i]) % MOD
	}

	// Compute the sum S
	S := 0
	for m := 0; m <= n-1; m++ {
		// Compute term = C(n-1, m) * 2^(n-1 - m) * (prefix[m] - prefix[max(0, m - k)])
		term := comb(n-1, m, fact, invFact)
		term = term * pow2[n-1-m] % MOD
		lower := m - k
		if lower < 0 {
			lower = 0
		}
		sumPart := (prefix[m] - prefix[lower] + MOD) % MOD
		term = term * sumPart % MOD
		S = (S + term) % MOD
	}

	// The answer is (n! - S) mod MOD
	ans := (fact[n] - S + MOD) % MOD
	fmt.Println(ans)
}

// comb computes C(n, k) using precomputed factorials and inverse factorials
func comb(n, k int, fact, invFact []int) int {
	if k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD
}

// modInv computes the modular inverse of a under modulo mod using Fermat's little theorem
func modInv(a, mod int) int {
	return powMod(a, mod-2, mod)
}

// powMod computes (base^exponent) mod mod using fast exponentiation
func powMod(base, exponent, mod int) int {
	result := 1
	base = base % mod
	for exponent > 0 {
		if exponent%2 == 1 {
			result = (result * base) % mod
		}
		exponent = exponent / 2
		base = (base * base) % mod
	}
	return result
}
