		inv[i] = (MOD - MOD/i) * inv[MOD%i] % MOD
	}

	comb := make([]int, n+1)
	comb[0] = 1
	for i := 1; i <= n; i++ {
		comb[i] = comb[i-1] * (n - i + 1) % MOD * inv[i] % MOD
	}

