package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(reader, &n, &k)

	if n == 1 {
		fmt.Println(0)
		return
	}

	// Precompute factorials and inverse factorials up to n
	fact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % MOD
	}

	inv_fact := make([]int, n+1)
	inv_fact[n] = modInv(fact[n], MOD)
	for i := n - 1; i >= 0; i-- {
		inv_fact[i] = inv_fact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2 up to n
	pow2 := make([]int, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}

	// Precompute inverse powers of 2
	inv_pow2 := make([]int, n+1)
	inv_pow2[0] = 1
	inv_2 := modInv(2, MOD)
	for i := 1; i <= n; i++ {
		inv_pow2[i] = inv_pow2[i-1] * inv_2 % MOD
	}

	// Precompute prefix sums of inv_pow2
	prefix_inv_pow2 := make([]int, n+1)
	prefix_inv_pow2[0] = inv_pow2[0]
	for i := 1; i <= n; i++ {
		prefix_inv_pow2[i] = (prefix_inv_pow2[i-1] + inv_pow2[i]) % MOD
	}

	// Precompute prefix sums of i * inv_pow2[i]
	prefix_i_inv_pow2 := make([]int, n+1)
	prefix_i_inv_pow2[0] = 0
	for i := 1; i <= n; i++ {
		prefix_i_inv_pow2[i] = (prefix_i_inv_pow2[i-1] + i*inv_pow2[i]) % MOD
	}

	total := 0
	for m := 1; m <= n-1; m++ {
		// Compute S(m, k)
		var S int
		if k > m {
			S = 0
		} else {
			// S = sum_{i=0}^{m-k} (m-i) * inv_pow2[i]
			// = m * sum_{i=0}^{m-k} inv_pow2[i] - sum_{i=0}^{m-k} i * inv_pow2[i]
			upper := m - k
			if upper < 0 {
				S = 0
			} else {
				sum_inv_pow2 := prefix_inv_pow2[upper]
				sum_i_inv_pow2 := prefix_i_inv_pow2[upper]
				S = (m*sum_inv_pow2 - sum_i_inv_pow2) % MOD
				if S < 0 {
					S += MOD
				}
			}
		}

		// Compute term = C(n-1, m) * fact[m] * pow2[m] * S
		// C(n-1, m) = fact[n-1] * inv_fact[m] * inv_fact[n-1-m]
		comb := fact[n-1] * inv_fact[m] % MOD
		comb = comb * inv_fact[n-1-m] % MOD
		term := comb * fact[m] % MOD
		term = term * pow2[m] % MOD
		term = term * S % MOD
		total = (total + term) % MOD
	}

	fmt.Println(total)
}

func modInv(a, mod int) int {
	return powMod(a, mod-2, mod)
}

func powMod(a, b, mod int) int {
	res := 1
	a = a % mod
	for b > 0 {
		if b%2 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b = b / 2
	}
	return res
}
