package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)

	if n == 1 {
		fmt.Println(0)
		return
	}

	// Precompute factorials and inverse factorials up to n
	fact := make([]int, n+1)
	invFact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % MOD
	}

	// Fermat's little theorem for inverse factorial
	invFact[n] = pow(fact[n], MOD-2, MOD)
	for i := n - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * (i + 1) % MOD
	}

	// Precompute powers of 2 up to n
	pow2 := make([]int, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = pow2[i-1] * 2 % MOD
	}

	// Precompute inverse powers of 2
	inv2 := pow(2, MOD-2, MOD)
	invPow2 := make([]int, n+1)
	invPow2[0] = 1
	for i := 1; i <= n; i++ {
		invPow2[i] = invPow2[i-1] * inv2 % MOD
	}

	// Compute the answer
	ans := 0
	for m := 0; m < n; m++ {
		// Calculate C(n-1, m)
		c := comb(n-1, m, fact, invFact)
		// Calculate 2^(n-1-m)
		p := pow2[n-1-m]
		// Calculate (m+1)^(k-1)
		// We need to compute (m+1)^(k-1) mod MOD
		// But for large exponents, we use fast exponentiation
		// However, since m can be up to n-1 and k up to 1e6, we need to compute this efficiently
		// We'll compute it using fast exponentiation
		exp := pow(m+1, k-1, MOD)
		// Calculate the term: C(n-1, m) * 2^(n-1-m) * (m+1)^(k-1)
		term := c * p % MOD
		term = term * exp % MOD
		ans = (ans + term) % MOD
	}

	// Multiply by n! / 2^(n-1)
	// Which is fact[n] * invPow2[n-1]
	result := ans * fact[n] % MOD
	result = result * invPow2[n-1] % MOD

	fmt.Println(result)
}

func comb(n, k int, fact, invFact []int) int {
	if k < 0 || k > n {
		return 0
	}
	return fact[n] * invFact[k] % MOD * invFact[n-k] % MOD
}

func pow(base, exp, mod int) int {
	result := 1
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}
