	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)

	if n == 1 {
		fmt.Println(0)
		return
	}

	fact = make([]int, n+1)
	inv = make([]int, n+1)
	ifact = make([]int, n+1)

	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * i % MOD
	}

	inv[1] = 1
	for i := 2; i <= n; i++ {
		inv[i] = MOD - (MOD/i)*inv[MOD%i] % MOD
	}

	ifact[0] = 1
	for i := 1; i <= n; i++ {
		ifact[i] = ifact[i-1] * inv[i] % MOD
	}

	// Compute S = sum_{j=0}^{n-1} (n-1-j)! / (n-1-j)! * ... 
	// Actually S = sum_{j=0}^{n-1} C(n-1, j) * j! 
	// But C(n-1,j)*j! = (n-1)! / (n-1-j)!
	// So S = (n-1)! * sum_{j=0}^{n-1} 1/(n-1-j)!
	// Let m = n-1-j, when j=0, m=n-1; j=n-1, m=0
	// S = (n-1)! * sum_{m=0}^{n-1} 1/m!

	// Compute sum_{m=0}^{n-1} 1/m! mod MOD
	invFactSum := 0
	for m := 0; m <= n-1; m++ {
		invFactSum = (invFactSum + ifact[m]) % MOD
	}

	S := fact[n-1] * invFactSum % MOD

	// Answer = n! - S
	ans := (fact[n] - S + MOD) % MOD
	fmt.Println(ans)
}
